def mover_decisiones_del_convenio(apps, schema_editor):
    """DC-59 (HU-60): las reservas que el contacto del convenio decidió antes de este cambio quedaron con actor
    PASAJERO. La autorización pasa a `autorizado_por_correo`/`autorizado_en` (actor SISTEMA) y el rechazo, al
    origen CONVENIO. Idempotente."""
    Viaje = apps.get_model("reservas", "Viaje")
    HistorialEstado = apps.get_model("reservas", "HistorialEstado")
    decididas = Viaje.objects.filter(confirma_convenio=True).select_related("convenio__usuario")
    for viaje in decididas.exclude(estado__in=["PENDIENTE_CONFIRMACION", "CANCELADO"]):
        paso = HistorialEstado.objects.filter(
            viaje=viaje, estado_anterior="PENDIENTE_CONFIRMACION", estado_nuevo="SOLICITADO", actor="PASAJERO"
        ).first()
        if paso is None or viaje.autorizado_en:
            continue
        convenio = viaje.convenio
        correo = convenio.contacto_correo or (convenio.usuario.email if convenio.usuario_id else None)
        Viaje.objects.filter(pk=viaje.pk).update(autorizado_por_correo=correo, autorizado_en=paso.creado_en)
        HistorialEstado.objects.filter(pk=paso.pk).update(actor="SISTEMA")
    rechazadas = decididas.filter(estado="CANCELADO", origen_cancelacion="SUPERVISOR")
    for viaje in rechazadas:
        HistorialEstado.objects.filter(viaje=viaje, estado_nuevo="CANCELADO", actor="PASAJERO").update(actor="SISTEMA")
    rechazadas.update(origen_cancelacion="CONVENIO")


